import { useEffect, useState, useContext } from 'react';
import axios from 'axios';
import { useSearchParams } from 'react-router-dom';
import Result from '../components/Result';
import AuthContext from '../context/AuthContext';

function History() {
  const [resumes, setResumes] = useState([]);
  const [page, setPage] = useState(1);
  const [pages, setPages] = useState(1);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(false);
  const [searchParams] = useSearchParams();
  const initialJobId = searchParams.get('jobId') || '';

  const [filters, setFilters] = useState({
    from: '',
    to: '',
    minScore: '',
    q: '',
    limit: 10,
    jobId: initialJobId
  });

  const [openId, setOpenId] = useState(null);
  const [currentEdit, setCurrentEdit] = useState({});
  const { user } = useContext(AuthContext);

  const STATUS_OPTIONS = ['Not Reviewed', 'Shortlisted', 'Rejected', 'Interview Scheduled', 'Interviewed', 'Offer Extended', 'Hired'];

  useEffect(() => {
    load();
  }, [page, filters]);

  async function load() {
    setLoading(true);
    try {
      const params = { page, limit: filters.limit };
      if (filters.minScore) params.minScore = filters.minScore;
      if (filters.from) params.from = filters.from;
      if (filters.to) params.to = filters.to;
      if (filters.q) params.q = filters.q;
      if (filters.jobId) params.jobId = filters.jobId;

      const res = await axios.get('/api/resume/my', { params, withCredentials: true });
      setResumes(res.data.data);
      setTotal(res.data.total || res.data.data?.length || 0);
      setPages(res.data.pages || 1);
      setOpenId(null);
      setCurrentEdit({});
    } catch (err) {
      console.error('Load error:', err);
      alert('Failed to load history');
    } finally {
      setLoading(false);
    }
  }

  async function updateStatus(id, newStatus, note = '') {
    try {
      const payload = { status: newStatus, note: note || 'Quick action' };
      const res = await axios.post(`/api/resume/${id}/status`, payload, { withCredentials: true });
      const updated = res.data.data;
      setResumes(prev => prev.map(r => r._id === id ? updated : r));
    } catch (err) {
      console.error('Status update error:', err);
      alert('Failed to update status');
    }
  }

  function getRecommendation(score) {
    if (score >= 85) return { label: 'Top Pick', class: 'score-good' };
    if (score >= 70) return { label: 'Highly Recommended', class: 'bg-primary' };
    if (score >= 50) return { label: 'Potential Match', class: 'score-warn' };
    return { label: 'Low Match', class: 'score-bad' };
  }

  return (
    <div className="page mt-6">
      <div className="container">
        <header className="flex justify-between items-end mb-8">
          <div>
            <h2 className="text-2xl font-black mb-1">Application History</h2>
            <p className="muted">Ranking candidates by match score and qualifications.</p>
          </div>
          {user?.role === 'recruiter' && (
            <span className="badge bg-accent px-4 py-2" style={{ borderRadius: '20px', fontWeight: 700 }}>
              Recruiter Mode
            </span>
          )}
        </header>

        <section className="card mb-8">
          <div className="grid grid-cols-1 md:grid-cols-4 gap-4 items-end">
            <div className="form-group mb-0">
              <label className="form-label mb-2 text-xs uppercase muted font-bold">Min Score</label>
              <input
                type="number"
                className="form-input"
                value={filters.minScore}
                onChange={(e) => setFilters({ ...filters, minScore: e.target.value })}
              />
            </div>
            <div className="form-group mb-0">
              <label className="form-label mb-2 text-xs uppercase muted font-bold">From Date</label>
              <input
                type="date"
                className="form-input"
                value={filters.startDate}
                onChange={(e) => setFilters({ ...filters, startDate: e.target.value })}
              />
            </div>
            <div className="form-group mb-0">
              <label className="form-label mb-2 text-xs uppercase muted font-bold">Search</label>
              <input
                type="text"
                className="form-input"
                placeholder="Name or skills..."
                value={filters.search}
                onChange={(e) => setFilters({ ...filters, search: e.target.value })}
              />
            </div>
            <div className="flex gap-2">
              <button className="btn btn-primary flex-1" onClick={() => setPage(1)}>Filter</button>
              <button className="btn btn-ghost" onClick={() => setFilters({ minScore: '', startDate: '', search: '', limit: 10, jobId: '' })}>Reset</button>
            </div>
          </div>
        </section>

        {loading ? (
          <div className="text-center py-10"><p className="muted">Ranking candidates...</p></div>
        ) : (
          <div className="flex flex-col gap-6">
            <p className="muted font-bold text-sm">{total} Applications Found</p>

            <div className="grid gap-4">
              {resumes.map((r, index) => {
                const rec = getRecommendation(r.score || 0);
                return (
                  <div key={r._id} className="card hover-shadow border-l-4" style={{ borderLeftColor: r.score >= 70 ? 'var(--success)' : (r.score >= 40 ? '#f59e0b' : 'var(--danger)') }}>
                    <div className="flex flex-col md:flex-row justify-between gap-6">
                      <div className="flex-1">
                        <div className="flex items-center flex-wrap gap-2 mb-4">
                          <span className="text-sm muted font-bold">#{index + 1 + (page - 1) * filters.limit}</span>
                          <h4 className="text-base font-bold m-0">{r.fileName?.split('-')[1] || 'Candidate Resume'}</h4>
                          <span className={`badge ${rec.class}`}>{rec.label}</span>
                          {r.jobId?.title && <span className="badge bg-secondary">Role: {r.jobId.title}</span>}
                        </div>

                        <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-4">
                          <div className="bg-slate-50 p-3 rounded-lg border border-slate-100">
                            <span className="block text-[10px] muted uppercase font-black mb-1">Match Score</span>
                            <span className="text-2xl font-black" style={{ color: r.score >= 70 ? 'var(--success)' : (r.score >= 40 ? '#f59e0b' : 'var(--danger)') }}>
                              {Math.round(r.score || 0)}%
                            </span>
                          </div>
                          <div className="col-span-1 md:col-span-2 bg-slate-50 p-3 rounded-lg border border-slate-100">
                            <span className="block text-[10px] muted uppercase font-black mb-1">Top Matches</span>
                            <div className="flex flex-wrap gap-1">
                              {(r.matchedSkills || []).slice(0, 6).map((s, i) => (
                                <span key={i} className="badge bg-white shadow-sm" style={{ border: '1px solid #e2e8f0' }}>{s}</span>
                              ))}
                            </div>
                          </div>
                          <div className="bg-slate-50 p-3 rounded-lg border border-slate-100">
                            <span className="block text-[10px] muted uppercase font-black mb-1">Status</span>
                            <span className={`badge ${r.interviewStatus === 'Shortlisted' ? 'bg-success' : (r.interviewStatus === 'Rejected' ? 'bg-danger' : 'bg-secondary')}`}>
                              {r.interviewStatus}
                            </span>
                          </div>
                        </div>

                        <div className="flex items-center gap-4 text-xs muted font-bold">
                          <span>Applied {new Date(r.createdAt).toLocaleDateString()}</span>
                        </div>
                      </div>

                      <div className="flex flex-col sm:flex-row md:flex-col gap-2 justify-center" style={{ minWidth: '160px' }}>
                        <button className="btn btn-ghost w-full" onClick={() => setOpenId(openId === r._id ? null : r._id)}>
                          {openId === r._id ? 'Close Details' : 'View Analysis'}
                        </button>

                        {['recruiter', 'admin'].includes(user?.role) && r.interviewStatus === 'Not Reviewed' && (
                          <div className="flex gap-2">
                            <button className="btn btn-success flex-1" onClick={() => updateStatus(r._id, 'Shortlisted')}>Shortlist</button>
                            <button className="btn btn-danger flex-1" onClick={() => updateStatus(r._id, 'Rejected')}>Reject</button>
                          </div>
                        )}
                      </div>
                    </div>

                    {openId === r._id && (
                      <div className="mt-6 pt-6 border-t border-slate-100">
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                          <div>
                            <h5 className="text-sm font-bold mb-3 flex items-center gap-2">
                              <div style={{ width: 8, height: 8, borderRadius: '50%', background: 'var(--success)' }} />
                              Strengths & Matches
                            </h5>
                            <div className="flex flex-wrap gap-2 text-sm">
                              {(r.matchedSkills || []).map((s, i) => (
                                <span key={i} className="chip">{s}</span>
                              ))}
                            </div>
                          </div>
                          <div>
                            <h5 className="text-sm font-bold mb-3 flex items-center gap-2">
                              <div style={{ width: 8, height: 8, borderRadius: '50%', background: 'var(--danger)' }} />
                              Skill Gaps
                            </h5>
                            <div className="flex flex-wrap gap-2 text-sm">
                              {(r.missingSkills || []).map((s, i) => (
                                <span key={i} className="chip missing">{s}</span>
                              ))}
                            </div>
                          </div>
                        </div>
                      </div>
                    )}
                  </div>
                );
              })}
            </div>

            <div className="flex justify-center items-center gap-4 py-8">
              <button className="btn btn-ghost" disabled={page === 1} onClick={() => setPage(p => p - 1)}>Previous</button>
              <span className="font-bold text-sm">Page {page} of {Math.ceil(total / filters.limit)}</span>
              <button className="btn btn-ghost" disabled={page >= Math.ceil(total / filters.limit)} onClick={() => setPage(p => p + 1)}>Next</button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

export default History;
